const rawOriginal = $input.item.json;

// --- Limpiar prefijos de grupo de KoboToolbox ---
const raw = {};
for (const [k, v] of Object.entries(rawOriginal)) {
  const cleanKey = k.includes('/') ? k.split('/').pop() : k;
  raw[cleanKey] = v;
}

// Normalizar key: minusculas, sin acentos, no-alfanum -> _
const norm = (s) => s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]/g, '_').replace(/_+/g, '_').replace(/^_|_$/g, '');

// Mapa normalizado para busqueda flexible
const rawNorm = {};
for (const [k, v] of Object.entries(raw)) {
  rawNorm[norm(k)] = v;
}

const LIKERT = {
  'totalmente de acuerdo':5,'muy de acuerdo':5,'completamente de acuerdo':5,
  'de acuerdo':4,'bastante de acuerdo':4,
  'ni de acuerdo ni en desacuerdo':3,'neutral':3,'indeciso':3,'indiferente':3,
  'en desacuerdo':2,'poco de acuerdo':2,
  'totalmente en desacuerdo':1,'muy en desacuerdo':1,'completamente en desacuerdo':1,
  'siempre':5,'casi siempre':4,'a veces':3,'casi nunca':2,'nunca':1,
  'frecuentemente':4,'ocasionalmente':3,'raramente':2,
  'muy satisfecho':5,'muy satisfecha':5,'satisfecho':4,'satisfecha':4,
  'regular':3,'insatisfecho':2,'insatisfecha':2,'muy insatisfecho':1,'muy insatisfecha':1,
  'excelente':5,'muy bueno':4,'muy buena':4,'bueno':3,'buena':3,
  'malo':2,'mala':2,'muy malo':1,'muy mala':1,
  'mucho':5,'bastante':4,'algo':3,'poco':2,'nada':1,
  'muy importante':5,'importante':4,'moderadamente importante':3,'poco importante':2,'sin importancia':1,
  'muy probable':5,'probable':4,'posible':3,'poco probable':2,'improbable':1,
  'si':1,'sí':1,'yes':1,'no':0
};

// Busqueda exacta normalizada
const buscar = (claves) => {
  for (const c of claves) {
    const n = norm(c);
    if (rawNorm[n] !== undefined && rawNorm[n] !== null && rawNorm[n] !== '') return String(rawNorm[n]);
  }
  return '';
};

// Busqueda con coincidencia parcial (para campos con nombres largos como preguntas completas)
const buscarParcial = (claves) => {
  const r = buscar(claves);
  if (r) return r;
  for (const c of claves) {
    const n = norm(c);
    if (n.length < 5) continue;
    for (const [k, v] of Object.entries(rawNorm)) {
      if (k.includes(n) && v !== undefined && v !== null && v !== '') return String(v);
    }
  }
  return '';
};

const uid = raw['_xform_id_string'] || '';
const FORMS = {
  'akz5K2bGfvvisQaE7VaHev':'C_01 Hoja de Interes 2025',
  'auvEELWQEgiwF54W4pGpV5':'C_01 Hoja de Interes 2026',
  'aF4nMQPqbHokM7rg2Vtf5w':'IL_01 Entrevista',
  'a5e8sJrazPBYXwTn6om35g':'IL_02 Convenio',
  'aNpJWVRoxxQ5a8pwBQVJac':'IL_03 Estipendios',
  'agz54DYND9t65j87ZVawXJ':'IL_05.1 Pre-Test',
  'a7fECFfTZLqfQifAcN8rFN':'IL_05.2 Post-Test',
  'aaiAih46xeGwR8YbSnwe7k':'IL_05 Satisfaccion Formacion',
  'aKPtMoCx6tFzagpLoWysuq':'IL_06 Satisfaccion Empleo',
  'aFYYHnU4BGs4stdTiLFENF':'IL_07 Empleos Directos',
  'azWEsFBnHSUvfVugsTcgTD':'IL_08 Acompanamiento',
  'aLNouQjf9UF7CJvDmRozCV':'IL_Pre_Post Orientacion 2026'
};

// --- NOMBRE COMPLETO: combinar Nombre(s) + Apellido(s) si no hay nombre_completo ---
let nombre = buscar(['nombre_completo','full_name']);
if (!nombre) {
  const nombres = buscar(['nombre_s','nombres','nombre','first_name']);
  const apellidos = buscar(['apellido_s','apellidos','apellido','last_name']);
  if (nombres && apellidos) nombre = nombres + ' ' + apellidos;
  else if (nombres) nombre = nombres;
  else if (apellidos) nombre = apellidos;
}

const creamos_id = buscar(['creamos_id','id_creamos','creamos']);

// GENERO: buscar Género, genero, sexo, etc.
const genero = buscar(['genero','gender','sexo','sex']);

// NIVEL EDUCATIVO: puede ser pregunta larga como "cual es tu ultimo nivel de estudios terminado"
const nivel_educativo = buscarParcial(['nivel_educativo','nivel_escolar','educacion','education','nivel_de_estudios','estudios_terminado','nivel_estudios']);

// EDAD: calcular de fecha de nacimiento si no existe campo directo
let edad = buscar(['edad','age']);
if (!edad) {
  const fechaNac = buscar(['fecha_de_nacimiento','fecha_nacimiento','birth_date','birthdate']);
  if (fechaNac) {
    try {
      const birth = new Date(fechaNac);
      const today = new Date();
      if (!isNaN(birth.getTime())) {
        edad = String(Math.floor((today - birth) / (365.25 * 24 * 60 * 60 * 1000)));
      }
    } catch(e) {}
  }
}

const out = {
  kobo_id:         String(raw['_id'] || ''),
  creamos_id,
  formulario:      FORMS[uid] || uid,
  fecha_envio:     raw['_submission_time'] ? raw['_submission_time'].substring(0,10) : '',
  nombre_completo: nombre,
  edad:            edad,
  genero:          genero,
  zona:            buscar(['zona','zone','area']),
  colonia:         buscar(['colonia','neighborhood','barrio']),
  nivel_educativo: nivel_educativo,
};

// Campos ya extraidos (normalizados) para no duplicar
const OMITIR_NORM = new Set([
  '_id','_xform_id_string','_submission_time','_uuid','_notes',
  '_status','_submitted_by','_tags','_validation_status','_bamboo_dataset_id',
  '_attachments','_geolocation','formhub','meta','__version__','_version_',
  'meta/instanceid','instanceid','end','start','today','deviceid','phonenumber',
  '_index','nombre_completo','full_name','nombre_s','nombres','nombre',
  'first_name','apellido_s','apellidos','apellido','last_name',
  'edad','age','fecha_de_nacimiento','fecha_nacimiento','birth_date','birthdate',
  'genero','gender','sexo','sex',
  'zona','zone','area','colonia','neighborhood','barrio',
  'nivel_educativo','nivel_escolar','educacion','education',
  'creamos_id','id_creamos','creamos',
  'nombre_preferido'
].map(x => norm(x)));

let puntaje_total = 0, campos_escala = 0;

for (const [k, v] of Object.entries(raw)) {
  const nk = norm(k);
  if (k.startsWith('_') || OMITIR_NORM.has(nk)) continue;
  // Skip fields with long question names about education level (already extracted)
  if (nk.includes('nivel_de_estudios') || nk.includes('estudios_terminado')) continue;
  if (typeof v === 'object' && v !== null) continue;
  const valor = v !== null && v !== undefined ? String(v) : '';
  if (valor === '') continue;
  out[k] = valor;
  const lower = valor.toLowerCase().trim();
  if (LIKERT[lower] !== undefined) {
    out[k + '_num'] = LIKERT[lower];
    puntaje_total += LIKERT[lower]; campos_escala++;
  } else if (!isNaN(parseFloat(valor)) && isFinite(valor)) {
    const num = parseFloat(valor);
    if (num >= 0 && num <= 10) {
      out[k + '_num'] = num;
      puntaje_total += num; campos_escala++;
    }
  }
}

if (campos_escala > 0) {
  out.puntaje_total        = puntaje_total;
  out.promedio_escala      = Math.round(puntaje_total / campos_escala * 100) / 100;
  out.total_pregs_escala   = campos_escala;
}

return out;

// Agregar todos los items en un solo array de valores para la API de Google Sheets
const items = $input.all().map(i => i.json);
if (!items.length) return [{ json: { values: [], count: 0 } }];
const headers = Object.keys(items[0]);
const rows = items.map(row => headers.map(h => {
  const v = row[h];
  return v !== undefined && v !== null ? String(v) : '';
}));
return [{ json: { values: [headers, ...rows], count: items.length } }];

// =====================================================
// MEGA TABLA IL - Una fila por participante (solo creamos_id)
// =====================================================
const allItems = $('Limpiar y Escalar').all().map(i => i.json);

const FORMULARIOS_IL = [
  { key: 'C_01 Hoja de Interes 2025', col: 'interes_2025',   escala: false, etapa: 'Inscripcion' },
  { key: 'C_01 Hoja de Interes 2026', col: 'interes_2026',   escala: false, etapa: 'Inscripcion' },
  { key: 'IL_01 Entrevista',          col: 'entrevista',     escala: false, etapa: 'Ingreso' },
  { key: 'IL_02 Convenio',            col: 'convenio',       escala: false, etapa: 'Ingreso' },
  { key: 'IL_03 Estipendios',         col: 'estipendios',    escala: false, etapa: 'Proceso' },
  { key: 'IL_05.1 Pre-Test',          col: 'pre_test',       escala: true,  etapa: 'Evaluacion' },
  { key: 'IL_05.2 Post-Test',         col: 'post_test',      escala: true,  etapa: 'Evaluacion' },
  { key: 'IL_05 Satisfaccion Formacion', col: 'sat_formacion', escala: true, etapa: 'Satisfaccion' },
  { key: 'IL_06 Satisfaccion Empleo', col: 'sat_empleo',     escala: true,  etapa: 'Satisfaccion' },
  { key: 'IL_07 Empleos Directos',    col: 'empleos',        escala: false, etapa: 'Resultado' },
  { key: 'IL_08 Acompanamiento',      col: 'acompanamiento', escala: false, etapa: 'Seguimiento' },
  { key: 'IL_Pre_Post Orientacion 2026', col: 'orient_2026', escala: true,  etapa: 'Evaluacion' }
];

// Agrupar por creamos_id. Si no tiene creamos_id, intentar por nombre normalizado
const porParticipante = {};

for (const reg of allItems) {
  // Llave principal: creamos_id
  let pid = (reg.creamos_id && reg.creamos_id.trim() !== '') ? reg.creamos_id.trim() : '';

  // Si no tiene creamos_id, usar nombre normalizado como llave temporal
  if (!pid && reg.nombre_completo && reg.nombre_completo.trim() !== '') {
    pid = 'NOMBRE:' + reg.nombre_completo.toLowerCase().trim().replace(/\s+/g, ' ');
  }

  if (!pid) continue;

  if (!porParticipante[pid]) {
    porParticipante[pid] = { datos: {}, formularios: {}, fechas: [] };
  }
  const p = porParticipante[pid];

  // Guardar datos demograficos (tomar el mas reciente no-vacio)
  const campos = ['nombre_completo','edad','genero','zona','colonia','nivel_educativo'];
  for (const c of campos) {
    if (reg[c] && reg[c] !== '') p.datos[c] = reg[c];
  }

  // Si tiene creamos_id, guardarlo
  if (reg.creamos_id && reg.creamos_id.trim() !== '') {
    p.datos.creamos_id = reg.creamos_id.trim();
  }

  const formName = reg.formulario || '';
  p.formularios[formName] = {
    fecha: reg.fecha_envio || '', kobo_id: reg.kobo_id || '',
    puntaje_total: reg.puntaje_total, promedio_escala: reg.promedio_escala,
    total_pregs: reg.total_pregs_escala
  };
  if (reg.fecha_envio) p.fechas.push(reg.fecha_envio);
}

const megaTabla = [];
for (const pid of Object.keys(porParticipante).sort()) {
  const p = porParticipante[pid];
  const d = p.datos;
  const f = p.formularios;
  const fechasOrd = p.fechas.sort();

  const fila = {
    creamos_id: d.creamos_id || (pid.startsWith('NOMBRE:') ? '' : pid),
    nombre_completo: d.nombre_completo || '',
    edad: d.edad || '', genero: d.genero || '', zona: d.zona || '',
    colonia: d.colonia || '', nivel_educativo: d.nivel_educativo || '',
    fecha_primer_contacto: fechasOrd[0] || '',
    fecha_ultimo_contacto: fechasOrd[fechasOrd.length - 1] || '',
    total_formularios: Object.keys(f).length,
  };

  let etapasCompletadas = new Set();
  for (const form of FORMULARIOS_IL) {
    const info = f[form.key];
    fila['il_' + form.col + '_ok'] = info ? 'Si' : 'No';
    fila['il_' + form.col + '_fecha'] = info ? info.fecha : '';
    if (info) etapasCompletadas.add(form.etapa);
    if (form.escala) {
      fila['il_' + form.col + '_puntaje'] = info && info.puntaje_total !== undefined ? info.puntaje_total : '';
      fila['il_' + form.col + '_promedio'] = info && info.promedio_escala !== undefined ? info.promedio_escala : '';
      fila['il_' + form.col + '_num_preguntas'] = info && info.total_pregs !== undefined ? info.total_pregs : '';
    }
  }

  const totalPosible = FORMULARIOS_IL.length;
  fila.pct_avance_formularios = Math.round(Object.keys(f).length / totalPosible * 100);
  fila.etapas_completadas = Array.from(etapasCompletadas).sort().join(', ');
  fila.num_etapas = etapasCompletadas.size;

  if (etapasCompletadas.has('Resultado')) fila.estado_participante = 'Egresado';
  else if (etapasCompletadas.has('Proceso') || etapasCompletadas.has('Evaluacion')) fila.estado_participante = 'En Proceso';
  else if (etapasCompletadas.has('Ingreso')) fila.estado_participante = 'Ingresado';
  else if (etapasCompletadas.has('Inscripcion')) fila.estado_participante = 'Inscrito';
  else fila.estado_participante = 'Registrado';

  const pre = f['IL_05.1 Pre-Test'];
  const post = f['IL_05.2 Post-Test'];
  fila.test_tiene_pre = pre ? 'Si' : 'No';
  fila.test_tiene_post = post ? 'Si' : 'No';
  fila.test_tiene_ambos = (pre && post) ? 'Si' : 'No';
  fila.test_pre_puntaje = pre && pre.puntaje_total !== undefined ? pre.puntaje_total : '';
  fila.test_post_puntaje = post && post.puntaje_total !== undefined ? post.puntaje_total : '';
  fila.test_pre_promedio = pre && pre.promedio_escala !== undefined ? pre.promedio_escala : '';
  fila.test_post_promedio = post && post.promedio_escala !== undefined ? post.promedio_escala : '';

  if (pre && post && pre.puntaje_total !== undefined && post.puntaje_total !== undefined) {
    fila.test_delta = post.puntaje_total - pre.puntaje_total;
    fila.test_pct_cambio = pre.puntaje_total > 0 ? Math.round((post.puntaje_total - pre.puntaje_total) / pre.puntaje_total * 100) : 0;
    fila.test_resultado = fila.test_delta > 0 ? 'Mejoro' : fila.test_delta < 0 ? 'Bajo' : 'Sin cambio';
  } else {
    fila.test_delta = ''; fila.test_pct_cambio = '';
    fila.test_resultado = pre && !post ? 'Pendiente Post-Test' : !pre && !post ? 'Sin Tests' : '';
  }

  const sf = f['IL_05 Satisfaccion Formacion'];
  const se = f['IL_06 Satisfaccion Empleo'];
  fila.sat_formacion_promedio = sf && sf.promedio_escala !== undefined ? sf.promedio_escala : '';
  fila.sat_empleo_promedio = se && se.promedio_escala !== undefined ? se.promedio_escala : '';
  const satValues = [sf, se].filter(s => s && s.promedio_escala !== undefined).map(s => s.promedio_escala);
  fila.sat_promedio_general = satValues.length > 0 ? Math.round(satValues.reduce((a,b) => a+b, 0) / satValues.length * 100) / 100 : '';

  fila.programa_barismo = ''; fila.programa_terapia = '';
  fila.programa_estudios = ''; fila.programa_empleo = '';
  fila.cohorte = '';
  fila.ultima_actualizacion = new Date().toISOString().substring(0, 10);

  megaTabla.push(fila);
}

if (megaTabla.length === 0) return [{ json: { sin_datos: 'No hay participantes' } }];
return megaTabla.map(fila => ({ json: fila }));

const items = $input.all().map(i => i.json);
if (!items.length) return [{ json: { values: [], count: 0 } }];
const headers = Object.keys(items[0]);
const rows = items.map(row => headers.map(h => {
  const v = row[h];
  return v !== undefined && v !== null ? String(v) : '';
}));
return [{ json: { values: [headers, ...rows], count: items.length } }];

const allItems = $('Limpiar y Escalar').all().map(i => i.json);
const registros = allItems || [];

const preTest = registros.filter(r => r.formulario && r.formulario.includes('Pre-Test'));
const postTest = registros.filter(r => r.formulario && r.formulario.includes('Post-Test'));

if (preTest.length === 0) return [{ json: { sin_datos: 'No hay registros Pre-Test aun' } }];

const numCols = preTest.length > 0 ? Object.keys(preTest[0]).filter(k => k.endsWith('_num')) : [];

const resultado = preTest.map(pre => {
  const post = postTest.find(p =>
    (pre.creamos_id && pre.creamos_id !== '' && p.creamos_id === pre.creamos_id) ||
    (pre.nombre_completo && p.nombre_completo &&
     pre.nombre_completo.toLowerCase().trim() === p.nombre_completo.toLowerCase().trim())
  );

  const fila = {
    creamos_id: pre.creamos_id || '',
    nombre_completo: pre.nombre_completo || '',
    edad: pre.edad || '', genero: pre.genero || '', zona: pre.zona || '',
    colonia: pre.colonia || '', nivel_educativo: pre.nivel_educativo || '',
    fecha_pre: pre.fecha_envio || '', fecha_post: post ? post.fecha_envio || '' : '',
    tiene_post_test: post ? 'Si' : 'No',
    puntaje_pre: pre.puntaje_total !== undefined ? pre.puntaje_total : '',
    puntaje_post: post && post.puntaje_total !== undefined ? post.puntaje_total : '',
    promedio_pre: pre.promedio_escala !== undefined ? pre.promedio_escala : '',
    promedio_post: post && post.promedio_escala !== undefined ? post.promedio_escala : '',
  };

  if (post && pre.puntaje_total !== undefined && post.puntaje_total !== undefined) {
    fila.delta_puntaje = post.puntaje_total - pre.puntaje_total;
    fila.pct_mejora = pre.puntaje_total > 0 ? Math.round(fila.delta_puntaje / pre.puntaje_total * 100) : 0;
    fila.resultado = fila.delta_puntaje > 0 ? 'Mejoro' : fila.delta_puntaje < 0 ? 'Bajo' : 'Sin cambio';
  }

  for (const col of numCols) {
    const base = col.replace('_num','');
    fila['pre_' + base] = pre[col] !== undefined ? pre[col] : '';
    fila['post_' + base] = post && post[col] !== undefined ? post[col] : '';
    if (post && pre[col] !== undefined && post[col] !== undefined) {
      fila['delta_' + base] = post[col] - pre[col];
    }
  }

  return { json: fila };
});

return resultado;

const items = $input.all().map(i => i.json);
if (!items.length) return [{ json: { values: [], count: 0 } }];
const headers = Object.keys(items[0]);
const rows = items.map(row => headers.map(h => {
  const v = row[h];
  return v !== undefined && v !== null ? String(v) : '';
}));
return [{ json: { values: [headers, ...rows], count: items.length } }];

// =====================================================
// INDICADORES IL - Cálculo automático desde datos Kobo
// =====================================================
const allItems = $('Limpiar y Escalar').all().map(i => i.json);
const megaItems = $('Crear Mega Tabla').all().map(i => i.json);

// --- Helpers ---
const uniqueBy = (arr, field) => {
  const seen = new Set();
  return arr.filter(r => {
    const v = r[field];
    if (!v || v === '' || seen.has(v)) return false;
    seen.add(v);
    return true;
  });
};

const countUnique = (arr, field) => {
  const s = new Set();
  arr.forEach(r => { if (r[field] && r[field] !== '') s.add(r[field]); });
  return s.size;
};

// --- Filtros por formulario ---
const hojaInteres = allItems.filter(r => r.formulario && r.formulario.includes('Hoja de Interes'));
const entrevista = allItems.filter(r => r.formulario && r.formulario.includes('Entrevista'));
const convenio = allItems.filter(r => r.formulario && r.formulario.includes('Convenio'));
const estipendios = allItems.filter(r => r.formulario && r.formulario.includes('Estipendios'));
const acomp = allItems.filter(r => r.formulario && r.formulario.includes('Acompanamiento'));
const satForm = allItems.filter(r => r.formulario && r.formulario.includes('Satisfaccion Formacion'));
const satEmpleo = allItems.filter(r => r.formulario && r.formulario.includes('Satisfaccion Empleo'));
const empleos = allItems.filter(r => r.formulario && r.formulario.includes('Empleos Directos'));
const preTest = allItems.filter(r => r.formulario && r.formulario.includes('Pre-Test'));
const postTest = allItems.filter(r => r.formulario && r.formulario.includes('Post-Test'));
const orientacion = allItems.filter(r => r.formulario && r.formulario.includes('Orientacion'));
const todosIL = allItems.filter(r => r.formulario && (r.formulario.startsWith('IL_') || r.formulario.includes('Interes')));

// --- Desagregación helper ---
const desagregar = (registros) => {
  const result = { total: countUnique(registros, 'creamos_id') };

  // Por género
  const porGenero = {};
  const unicos = uniqueBy(registros, 'creamos_id');
  unicos.forEach(r => {
    const g = (r.genero || 'Sin dato').trim();
    porGenero[g] = (porGenero[g] || 0) + 1;
  });
  result.por_genero = Object.entries(porGenero).map(([k,v]) => k + ': ' + v).join(', ');

  // Por nivel educativo
  const porNivel = {};
  unicos.forEach(r => {
    const n = (r.nivel_educativo || 'Sin dato').trim();
    porNivel[n] = (porNivel[n] || 0) + 1;
  });
  result.por_nivel_educativo = Object.entries(porNivel).map(([k,v]) => k + ': ' + v).join(', ');

  return result;
};

// --- CALCULAR INDICADORES ---
const indicadores = [];
const hoy = new Date().toISOString().substring(0, 10);

// IL.P.01 - Número de participantes en IL
const ilp01 = desagregar(todosIL);
indicadores.push({
  codigo: 'IL.P.01',
  criterio: 'Pertinencia',
  indicador: 'Número de participantes en IL',
  valor: ilp01.total,
  target_2026: 210,
  pct_avance: Math.round(ilp01.total / 210 * 100),
  por_genero: ilp01.por_genero,
  por_nivel_educativo: ilp01.por_nivel_educativo,
  fuente: 'Todos los formularios IL',
  fecha_calculo: hoy
});

// IL.P.02 - Participantes con Acompañamiento Profesional
const ilp02 = desagregar(acomp);
indicadores.push({
  codigo: 'IL.P.02',
  criterio: 'Pertinencia',
  indicador: 'Participantes con Acompañamiento Profesional',
  valor: ilp02.total,
  target_2026: 122,
